struct Fixture(PathBuf);
impl Fixture {
    fn new(name: &str, bytes: &[u8]) -> Self {
        use std::io::Write;
        let path =
            std::env::temp_dir().join(format!("hepta-legacy-byte-{name}-{}", std::process::id()));
        let mut file = OpenOptions::new()
            .read(true)
            .write(true)
            .create_new(true)
            .open(&path)
            .expect("new fixture");
        file.write_all(bytes).expect("write old bytes");
        file.sync_all().expect("sync old bytes");
        Self(path)
    }
    fn open(&self) -> File {
        OpenOptions::new()
            .read(true)
            .write(true)
            .open(&self.0)
            .expect("open fixture")
    }
    fn bytes(&self) -> Vec<u8> {
        fs::read(&self.0).expect("read fixture")
    }
}
impl Drop for Fixture {
    fn drop(&mut self) {
        let _ = fs::remove_file(&self.0);
    }
}
fn old_anchor() -> FinalHoldoutCasAnchorV1 {
    FinalHoldoutCasAnchorV1 {
        fence_generation: 1,
        record_count: 1,
        state_digest: OLD_STATE,
    }
}

#[test]
fn old_writer_bytes_recover_and_legacy_retry_never_append() {
    let f = Fixture::new("read", LEGACY_BYTES);
    let store =
        LockedFileFinalHoldoutCasStoreV1::recover(f.open(), d("binding"), Some(old_anchor()))
            .expect("read actual V1 file");
    let mut owner = FencedFinalHoldoutOwnerV1::recover(store, d("binding"), fence(1))
        .expect("same fence recover");
    assert_eq!(owner.anchor(), old_anchor());
    assert_eq!(owner.head_digest(), OLD_HEAD);
    let receipt = owner
        .consume(&ope("legacy", d("old cohort")))
        .expect("old retry");
    assert_eq!(
        receipt.disposition,
        HoldoutUseDispositionV1::IdempotentReplay
    );
    assert_eq!(receipt.record_digest, OLD_HEAD);
    assert_eq!(receipt.head_digest, OLD_HEAD);
    drop(owner);
    assert_eq!(f.bytes(), LEGACY_BYTES);
}

#[test]
fn append_paired_to_actual_old_bytes_preserves_prefix_and_recovers_once() {
    let f = Fixture::new("append", LEGACY_BYTES);
    let store =
        LockedFileFinalHoldoutCasStoreV1::recover(f.open(), d("binding"), Some(old_anchor()))
            .expect("read old");
    let mut owner =
        FencedFinalHoldoutOwnerV1::recover(store, d("binding"), fence(1)).expect("recover");
    let plan = paired("new-paired");
    let first = owner.consume_paired(&plan).expect("append tag 2");
    let anchor = owner.anchor();
    assert_eq!(anchor.record_count, 2);
    drop(owner);
    let appended = f.bytes();
    assert_eq!(&appended[..LEGACY_BYTES.len()], LEGACY_BYTES);
    assert_eq!(
        appended[LEGACY_BYTES.len() + 4],
        2,
        "new frame uses paired tag"
    );
    let store = LockedFileFinalHoldoutCasStoreV1::recover(f.open(), d("binding"), Some(anchor))
        .expect("reopen mixed bytes");
    let mut owner =
        FencedFinalHoldoutOwnerV1::recover(store, d("binding"), fence(1)).expect("recover mixed");
    let retry = owner.consume_paired(&plan).expect("paired retry");
    assert_eq!(retry.disposition, HoldoutUseDispositionV1::IdempotentReplay);
    assert_eq!(retry.record_digest, first.record_digest);
    assert_eq!(
        owner
            .consume(&ope("legacy", d("old cohort")))
            .expect("old retry")
            .record_digest,
        OLD_HEAD
    );
    assert_eq!(owner.anchor(), anchor);
    drop(owner);
    assert_eq!(f.bytes(), appended);
    fs::write(&f.0, LEGACY_BYTES).expect("restore old backup");
    assert_eq!(
        LockedFileFinalHoldoutCasStoreV1::recover(f.open(), d("binding"), Some(anchor)).err(),
        Some(LockedFileCasErrorV1::Rollback)
    );
    assert_eq!(f.bytes(), LEGACY_BYTES);
}

#[test]
fn corrupt_or_truncated_actual_old_bytes_are_rejected_without_rewrite() {
    let mut corrupt = LEGACY_BYTES.to_vec();
    *corrupt.last_mut().expect("nonempty") ^= 1;
    for (name, bytes) in [
        ("corrupt", corrupt),
        ("truncated", LEGACY_BYTES[..LEGACY_BYTES.len() - 1].to_vec()),
    ] {
        let f = Fixture::new(name, &bytes);
        assert_eq!(
            LockedFileFinalHoldoutCasStoreV1::recover(f.open(), d("binding"), Some(old_anchor()))
                .err(),
            Some(LockedFileCasErrorV1::Corrupt)
        );
        assert_eq!(f.bytes(), bytes);
    }
}
